-- Playerbots database only. Deterministic authored-clause combinations; no private data.
-- Existing chat frequency/probabilities are unchanged. Rerunning does not duplicate rows.
START TRANSACTION;
CREATE TEMPORARY TABLE bot_chat_seed (name VARCHAR(255), text VARCHAR(1024)) CHARACTER SET utf8mb4;
CREATE TEMPORARY TABLE bot_chat_existing (digest BINARY(32) PRIMARY KEY);
DROP TEMPORARY TABLE bot_chat_seed;
DROP TEMPORARY TABLE bot_chat_existing;
COMMIT;
